/bin/bash -lc "python - <<'PY'
import pathlib,re
for f in sorted(pathlib.Path('.').glob('*.txt')):
 s=f.read_text(); lines=s.splitlines(); page='?'; found=[]
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'governed|governing law|construed.*laws|California',l,re.I):
   found.append(f'p.{page}: '+ ' '.join(lines[max(0,i-1):i+4]))
 print('\\nFILE:',f.name[:-4]); print('\\n'.join(found) or 'NO MATCH')
PY"

